#!/usr/bin/env bash\n\n# List of whimsical quotes\nquotes=(\n"Even the darkest night ends with a sunrise."\n"The cactus whispers to the moon."\n"Stars are just nightlights for the universe."\n"Coffee is the fuel of the apocalypse."\n"Remember: socks disappear to a parallel dimension."\n)\n\n# Determine which quote to show\nif [[ -n "$QUOTE_INDEX" ]]; then\n  idx=$QUOTE_INDEX\nelse\n  # Generate a random index\n  idx=$(( RANDOM % ${#quotes[@]} ))\nfi\n\n# Ensure index is within bounds\nidx=$(( idx % ${#quotes[@]} ))\n\n# Output the selected quote\necho "${quotes[$idx]}"\n
